<script lang="ts">import{messageActionClassName}from'@fex-design/styles/message';import{cn}from'@fex/utils';import type{Snippet}from'svelte';import type{HTMLButtonAttributes}from'svelte/elements';import Toggle from'../toggle/toggle.svelte';interface Props extends Omit<HTMLButtonAttributes,'children'|'onchange'>{pressed?:boolean;defaultPressed?:boolean;onchange?:(value:boolean)=>void;children?:Snippet;render?:Snippet<[{props:Record<string,unknown>;state:{pressed:boolean;disabled:boolean}}]>}let{pressed,defaultPressed=false,disabled=false,onchange,class:className,children,render,...rest}:Props=$props();let state=$derived({pressed:pressed??defaultPressed,disabled:Boolean(disabled)});let binding=$derived({'data-slot':'message-action','data-state':state.pressed?'on':'off',class:cn(messageActionClassName(),className)})</script>{#if render}{@render render({props:binding,state})}{:else}<Toggle {...rest} {pressed} {defaultPressed} {disabled} variant="default" size="sm" data-slot="message-action" class={cn(messageActionClassName(),className)} {onchange}>{@render children?.()}</Toggle>{/if}
